  FILTER(?shortfall > 0) .
}"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:riskTolerance ?rt .
  FILTER(LCASE(?rt) = "moderate") .

  # PortfolioHealth with diversificationScore < 25
  {
    SELECT ?inv (MIN(?divScore) AS ?minDivScore)
    WHERE {
      ?inv wm:hasPortfolioHealth ?ph .
      ?ph wm:diversificationScore ?divScore .
    }
    GROUP BY ?inv
    HAVING (?minDivScore < 25)
  }

  # ScenarioRebalancing with scenario = "Bull Market"
  {
    SELECT ?inv (COUNT(?sr) AS ?srCount)
    WHERE {
      ?inv wm:hasScenarioRebalancing ?sr .
      ?sr wm:scenario ?scenario .
      FILTER(LCASE(?scenario) = "bull market")
    }
    GROUP BY ?inv
    HAVING (?srCount > 0)
  }

  # InvestmentGoal with shortfall > 0 (underfunded)
  {
    SELECT ?inv (COUNT(?goal) AS ?goalCount)
    WHERE {
      ?inv wm:hasInvestmentGoal ?goal .
      ?goal wm:shortfall ?sf .
      FILTER(?sf > 0)
    }
    GROUP BY ?inv
    HAVING (?goalCount > 0)
  }
}"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  ?investor a wm:Investor .
  ?investor wm:investorId ?investorId .
  ?investor wm:investorName ?investorName .
  ?investor wm:riskTolerance ?riskTol .
  FILTER(LCASE(STR(?riskTol)) = "moderate") .

  FILTER EXISTS {
    ?investor wm:hasPortfolioHealth ?ph .
    ?ph wm:diversificationScore ?divScore .
    FILTER(?divScore < 25) .
  }

  FILTER EXISTS {
    ?investor wm:hasScenarioRebalancing ?sr .
    ?sr wm:scenario ?scenario .
    FILTER(LCASE(STR(?scenario)) = "economic growth") .
  }

  FILTER EXISTS {
    ?investor wm:hasInvestmentGoal ?goal .
    ?goal wm:shortfall ?shortfall .
    FILTER(?shortfall > 0) .
  }
}"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:category "Aggressive" .

  ?ph a wm:PortfolioHealth ;
       wm:investorId ?investorId ;
       wm:riskScore ?riskScore .
  FILTER(?riskScore > 50)

  ?phold a wm:PortfolioHolding ;
         wm:investorId ?investorId ;
         wm:investmentName "Gold" .

  ?ra a wm:RebalancingAction ;
      wm:investorId ?investorId ;
      wm:action "De-risking" .

  ?goal a wm:InvestmentGoal ;
        wm:investorId ?investorId ;
        wm:shortfall ?shortfall .
  FILTER(?shortfall > 0)
}"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor rdf:type wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:riskTolerance "Conservative" .

  ?ph rdf:type wm:PortfolioHealth ;
      wm:healthOfInvestor ?investor ;
      wm:riskScore ?riskScore .
  FILTER(?riskScore > 50)

  ?holding rdf:type wm:PortfolioHolding ;
           wm:heldByInvestor ?investor ;
           wm:investmentName "Gold" .

  ?reb rdf:type wm:RebalancingAction ;
       wm:rebalancingActionOfInvestor ?investor ;
       wm:action "De-risking" .

  ?goal rdf:type wm:InvestmentGoal ;
        wm:belongsToInvestor ?investor ;
        wm:shortfall ?shortfall .
  FILTER(?shortfall > 0)
}"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:category "Conservative" .

  ?ph a wm:PortfolioHealth ;
      wm:riskScore ?riskScore ;
      wm:healthOfInvestor ?investor .
  FILTER(?riskScore > 50) .

  ?holding a wm:PortfolioHolding ;
           wm:investmentName "Gold" ;
           wm:heldByInvestor ?investor .

  ?reb a wm:RebalancingAction ;
       wm:action "Defensive Shift" ;
       wm:rebalancingActionOfInvestor ?investor .

  ?goal a wm:InvestmentGoal ;
        wm:shortfall ?shortfall ;
        wm:belongsToInvestor ?investor .
  FILTER(?shortfall > 0) .
}"}

