{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  # Investor with Aggressive risk tolerance
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:riskTolerance ?riskTol .
  FILTER(LCASE(?riskTol) = "aggressive")

  # PortfolioHealth linked to the investor with low liquidity
  ?ph a wm:PortfolioHealth ;
       wm:healthOfInvestor ?inv ;
       wm:liquidityScore ?liqScore .
  FILTER(?liqScore < 25)

  # Subquery counting loss‑making holdings for the investor
  {
    SELECT ?inv (COUNT(DISTINCT ?holdingId) AS ?loss_holding_count)
    WHERE {
      ?inv a wm:Investor .
      ?phold a wm:PortfolioHolding ;
              wm:heldByInvestor ?inv ;
              wm:holdingId ?holdingId ;
              wm:returnsPct ?ret ;
              wm:cost ?cost ;
              wm:currentValue ?curVal .
      FILTER(?ret < 0)
      FILTER(bound(?cost))
      FILTER(bound(?curVal))
    }
    GROUP BY ?inv
    HAVING (COUNT(DISTINCT ?holdingId) > 0)
  }
}"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  # Investor details and filters
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:riskTolerance ?rt .
  FILTER(LCASE(STR(?rt)) = "conservative") .

  # Portfolio health filter
  ?ph a wm:PortfolioHealth ;
      wm:healthOfInvestor ?inv ;
      wm:riskScore ?riskScore .
  FILTER(?riskScore > 75) .

  # Sub‑query counting loss‑making holdings per investor
  {
    SELECT ?investorId (COUNT(?holding) AS ?lossHoldingCount)
    WHERE {
      ?holding wm:heldByInvestor ?invH ;
               wm:returnsPct ?ret ;
               wm:cost ?cost ;
               wm:currentValue ?cv .
      ?invH wm:investorId ?investorId .
      FILTER(?ret < 0) .
      FILTER(bound(?cost)) .
      FILTER(bound(?cv)) .
    }
    GROUP BY ?investorId
  }

  FILTER(?lossHoldingCount > 0)
}"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  # Base investor with Conservative risk tolerance
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:riskTolerance ?riskTol .
  FILTER(LCASE(STR(?riskTol)) = "conservative") .

  # PortfolioHealth with riskScore > 75
  {
    SELECT ?investorId
    WHERE {
      ?invHealth a wm:Investor ;
                 wm:investorId ?investorId ;
                 wm:hasPortfolioHealth ?ph .
      ?ph wm:riskScore ?riskScore .
      FILTER(?riskScore > 75)
    }
    GROUP BY ?investorId
  }

  # At least one underfunded InvestmentGoal (shortfall > 0)
  {
    SELECT ?investorId (COUNT(?goal) AS ?goalCount)
    WHERE {
      ?invGoal a wm:Investor ;
               wm:investorId ?investorId ;
               wm:hasInvestmentGoal ?goal .
      ?goal wm:shortfall ?shortfall .
      FILTER(?shortfall > 0)
    }
    GROUP BY ?investorId
    HAVING (COUNT(?goal) > 0)
  }
}
GROUP BY ?investorId ?investorName"}

