{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  # Investor with Conservative risk tolerance
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:riskTolerance ?riskTol .
  FILTER(LCASE(STR(?riskTol)) = "conservative")

  # Portfolio health with diversificationScore < 25
  ?investor wm:hasPortfolioHealth ?ph .
  ?ph wm:diversificationScore ?divScore .
  FILTER(?divScore < 25)

  # Sector allocation in Consumer Goods with allocation > 0%
  ?investor wm:hasSectorAllocation ?sa .
  ?sa wm:sector ?sectorLabel ;
      wm:allocationPct ?allocPct .
  FILTER(LCASE(STR(?sectorLabel)) = "consumer goods")
  FILTER(?allocPct > 0)

  # Sub‑query: count loss‑making holdings per investor
  {
    SELECT ?investorId (COUNT(?holding) AS ?loss_holding_count)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?inv ;
               wm:cost ?cost ;
               wm:currentValue ?curr .
      FILTER(bound(?cost) && bound(?curr))
      FILTER(?cost > ?curr)
      ?inv wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  FILTER(?loss_holding_count > 0)
}
GROUP BY ?investorId ?investorName"}

