  FILTER EXISTS {
    ?inv wm:hasPortfolioHealth ?ph .
    ?ph wm:liquidityScore ?liq .
    FILTER(?liq < 50)
  }

  FILTER EXISTS {
    ?inv wm:hasSectorAllocation ?sa .
    ?sa wm:sector ?sectorLabel .
    ?sa wm:allocationPct ?alloc .
    FILTER(?alloc > 0 && LCASE(STR(?sectorLabel)) = "automobile")
  }

  FILTER EXISTS {
