    ?goal wm:shortfall ?sf .
    FILTER(?sf > 0)
  }
}"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  # Investor basics
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:segment ?segment .

  FILTER(LCASE(STR(?segment)) = "diversified")

  # Liquidity filter
  ?inv wm:hasPortfolioHealth ?ph .
  ?ph wm:liquidityScore ?liqScore .
  FILTER(?liqScore < 50)

  # Banking sector allocation > 0%
  FILTER EXISTS {
    ?inv wm:hasSectorAllocation ?sa .
    ?sa wm:sector ?sector ;
        wm:allocationPct ?allocPct .
    FILTER(LCASE(STR(?sector)) = "banking")
    FILTER(?allocPct > 0)
  }

  # Underfunded goal count > 0
  {
    SELECT ?inv (COUNT(?goal) AS ?underfundedGoalCount)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?inv ;
            wm:shortfall ?shortfall .
      FILTER(?shortfall > 0)
    }
    GROUP BY ?inv
  }
  FILTER(?underfundedGoalCount > 0)
}"}

