{"Q1": "PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:riskTolerance ?riskTol .
  FILTER (LCASE(STR(?riskTol)) = "aggressive")

  FILTER EXISTS {
    ?goal a wm:InvestmentGoal ;
          wm:investorId ?investorId ;
          wm:shortfall ?sf .
    FILTER (xsd:decimal(?sf) > 0)
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?amt)) AS ?netCashFlow2025)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:amount ?amt ;
          wm:date ?date .
      BIND (xsd:date(?date) AS ?dateTyped)
      FILTER ( ?dateTyped >= "2025-01-01"^^xsd:date && ?dateTyped <= "2025-12-31"^^xsd:date )
    }
    GROUP BY ?investorId
    HAVING (SUM(xsd:decimal(?amt)) < 0)
  }
}"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?net_cash_flow WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?net_cash_flow) WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:amount ?amount ;
          wm:date ?dateStr .
      BIND(xsd:date(?dateStr) AS ?date)
      FILTER(?date >= "2024-01-01"^^xsd:date && ?date <= "2024-12-31"^^xsd:date)
    }
    GROUP BY ?investorId
    HAVING (SUM(xsd:decimal(?amount)) < 0)
  }
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:timeHorizon ?timeHorizon .
  FILTER(?timeHorizon = "Short-term")
}"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?netCashFlow2025 WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  FILTER EXISTS {
    ?holding a wm:PortfolioHolding ;
             wm:investorId ?investorId ;
             wm:investmentType "Equity" .
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?netCashFlow2025) WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:amount ?amount ;
          wm:date ?date .
      FILTER ( xsd:date(?date) >= "2025-01-01"^^xsd:date && xsd:date(?date) <= "2025-12-31"^^xsd:date )
    }
    GROUP BY ?investorId
  }

  FILTER (?netCashFlow2025 < 0)
}"}
